import json
verdicts = {'pass':0, 'fail':0, 'err':0, 'timeout':0, 'syntax':0}
with open('/root/autodl-tmp/trace-verdict-study-data/raw_traces.jsonl') as f:
    for line in f:
        d = json.loads(line)
        if d['verdict']:
            verdicts['pass'] += 1
        else:
            err = d['test_results'].get('error','')
            if 'Timeout' in err:
                verdicts['timeout'] += 1
            elif 'SyntaxError' in err:
                verdicts['syntax'] += 1
            else:
                verdicts['err'] += 1
total = sum(verdicts.values())
print(f'Total: {total}')
for k,v in verdicts.items():
    print(f'  {k}: {v} ({100*v/max(total,1):.1f}%)')
"
